"""Exhaustive total-nonnegativity checker: enumerate every minor of a matrix
using exact fraction arithmetic and report which minors (if any) are negative."""
from __future__ import annotations
from fractions import Fraction
from itertools import combinations
from typing import List, Sequence

Matrix = List[List[Fraction]]

def det(mat: Matrix) -> Fraction:
    n = len(mat); a = [r[:] for r in mat]; d = Fraction(1)
    for col in range(n):
        piv = next((r for r in range(col, n) if a[r][col] != 0), None)
        if piv is None:
            return Fraction(0)
        if piv != col:
            a[col], a[piv] = a[piv], a[col]; d = -d
        d *= a[col][col]
        for r in range(col + 1, n):
            f = a[r][col] / a[col][col]
            for c in range(col, n):
                a[r][c] -= f * a[col][c]
    return d

def sub(mat: Matrix, rows: Sequence[int], cols: Sequence[int]) -> Matrix:
    return [[mat[r][c] for c in cols] for r in rows]

def check_tn(rows: Sequence[Sequence[float]]) -> None:
    M = [[Fraction(x) for x in r] for r in rows]
    m, n = len(M), len(M[0])
    negatives = []
    total = 0
    for k in range(1, min(m, n) + 1):
        for rs in combinations(range(m), k):
            for cs in combinations(range(n), k):
                total += 1
                if det(sub(M, rs, cs)) < 0:
                    negatives.append((rs, cs))
    print(f"examined {total} minors; negative minors: {negatives or 'none'}")

if __name__ == "__main__":
    check_tn([[1, 1, 1], [0, 1, 2], [0, 0, 1]])   # totally nonnegative
    check_tn([[1, 2, 0], [0, 1, 0], [1, 0, 1]])   # has a negative minor

"""Certify total nonnegativity of the 3x3 interval matrix by building it from the
identity with valid adjacent nonnegative column operations, checking TN at each step."""
from __future__ import annotations
from fractions import Fraction
from itertools import combinations
from typing import List

Matrix = List[List[Fraction]]

def det(a: Matrix) -> Fraction:
    n = len(a); a = [r[:] for r in a]; d = Fraction(1)
    for c in range(n):
        p = next((r for r in range(c, n) if a[r][c] != 0), None)
        if p is None:
            return Fraction(0)
        if p != c:
            a[c], a[p] = a[p], a[c]; d = -d
        d *= a[c][c]
        for r in range(c + 1, n):
            f = a[r][c] / a[c][c]
            for k in range(c, n):
                a[r][k] -= f * a[c][k]
    return d

def is_tn(M: Matrix) -> bool:
    m, n = len(M), len(M[0])
    return all(det([[M[r][c] for c in cs] for r in rs]) >= 0
               for k in range(1, min(m, n) + 1)
               for rs in combinations(range(m), k)
               for cs in combinations(range(n), k))

def col_op(M: Matrix, alpha: Fraction, src: int, tgt: int) -> Matrix:
    assert alpha >= 0 and tgt == src + 1, "operation must be valid and adjacent"
    R = [r[:] for r in M]
    for i in range(len(M)):
        R[i][tgt] = M[i][tgt] + alpha * M[i][src]
    return R

def main() -> None:
    M = [[Fraction(i == j) for j in range(3)] for i in range(3)]
    steps = [(Fraction(1), 1, 2), (Fraction(1), 0, 1), (Fraction(1), 1, 2)]
    print("seed identity TN:", is_tn(M))
    for alpha, s, t in steps:
        M = col_op(M, alpha, s, t)
        print(f"after add {alpha}*col{s}->col{t}: {M}  TN={is_tn(M)}")
    print("equals interval matrix H:", M == [[1,1,1],[0,1,2],[0,0,1]])

if __name__ == "__main__":
    main()

